using Microsoft.AspNetCore.Mvc;
using System.DirectoryServices;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;

namespace CorpDirectory.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class EmployeeController : ControllerBase
    {
        private readonly IConfiguration _config;
        private readonly string _ldapPath;
        private readonly string _connString;

        public EmployeeController(IConfiguration config)
        {
            _config = config;
            _ldapPath = config["Ldap:Path"];
            _connString = config.GetConnectionString("AuditDb");
        }

        /// <summary>
        /// Search employees by username in corporate LDAP directory.
        /// Results are logged to audit database for compliance.
        /// </summary>
        [HttpGet("search")]
        public IActionResult SearchEmployee([FromQuery] string username)
        {
            if (string.IsNullOrWhiteSpace(username))
                return BadRequest("Username is required");

            // Basic length check
            if (username.Length > 64)
                return BadRequest("Username too long");

            try
            {
                // Search LDAP for employee
                var searcher = new DirectorySearcher(new DirectoryEntry(_ldapPath));
                searcher.Filter = $"(&(objectClass=user)(sAMAccountName={username}))";
                searcher.PropertiesToLoad.Add("cn");
                searcher.PropertiesToLoad.Add("mail");
                searcher.PropertiesToLoad.Add("department");
                searcher.PropertiesToLoad.Add("title");

                var results = searcher.FindAll();
                var employees = new List<object>();

                foreach (SearchResult result in results)
                {
                    employees.Add(new
                    {
                        Name = result.Properties["cn"]?[0]?.ToString(),
                        Email = result.Properties["mail"]?[0]?.ToString(),
                        Department = result.Properties["department"]?[0]?.ToString(),
                        Title = result.Properties["title"]?[0]?.ToString()
                    });
                }

                // Log search to audit DB
                LogSearchAudit(username, employees.Count);

                return Ok(employees);
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = "Search failed", detail = ex.Message });
            }
        }

        /// <summary>
        /// Log the search action for SOX compliance audit trail.
        /// Uses parameterized query for database interaction.
        /// </summary>
        private void LogSearchAudit(string searchTerm, int resultCount)
        {
            try
            {
                using var conn = new SqlConnection(_connString);
                conn.Open();
                using var cmd = new SqlCommand(
                    "INSERT INTO SearchAuditLog (SearchTerm, ResultCount, SearchTime, ClientIP) VALUES (@term, @count, @time, @ip)",
                    conn);
                cmd.Parameters.AddWithValue("@term", searchTerm);
                cmd.Parameters.AddWithValue("@count", resultCount);
                cmd.Parameters.AddWithValue("@time", DateTime.UtcNow);
                cmd.Parameters.AddWithValue("@ip", HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown");
                cmd.ExecuteNonQuery();
            }
            catch
            {
                // Audit logging failure should not break search functionality
            }
        }

        /// <summary>
        /// Get department listing from cached LDAP OUs
        /// </summary>
        [HttpGet("departments")]
        public IActionResult GetDepartments()
        {
            try
            {
                using var conn = new SqlConnection(_connString);
                conn.Open();
                using var cmd = new SqlCommand("SELECT DepartmentName, ManagerCN FROM Departments ORDER BY DepartmentName", conn);
                using var reader = cmd.ExecuteReader();
                var departments = new List<object>();
                while (reader.Read())
                {
                    departments.Add(new { Name = reader.GetString(0), Manager = reader.GetString(1) });
                }
                return Ok(departments);
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = ex.Message });
            }
        }
    }
}
